/*"selectMasterMdAmInfoReferenceList"*/ SELECT /*+ index_asc(icomboard icomboard_pk) */ BID, COMPANY, SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) AS EMAIL, REG_DATE, (SELECT MAX (BID) FROM ICOMBOARD WHERE STATUS != 'D'
AND BTYPE NOT IN ('BD', 'QA')
AND BTYPE = #{sbtype}
) AS MAX_BID, (SELECT MIN (BID) FROM ICOMBOARD WHERE STATUS != 'D'
AND BTYPE NOT IN ('BD', 'QA')
AND BTYPE = #{sbtype}
) AS MIN_BID, ACL, LCOUNT, DECODE (BTYPE, 'NT', '공지사항', 'EB', 'e-Biz뉴스', 'DI', '전시회소식', 'EM', 'e마켓자료실', 'SI', '상품자료실', 'WM', '물류센터공지사항', 'PI', '구매정보') BTYPE_DIS, DECODE (ACL, 'INC', '자사', 'BUY', '구매사', 'SEL', '판매사', 'KEP', 'KEP', 'MEB', '회원전체', 'CST', '회사선택', 'UST', '사용자선택', 'ALL', '전체') ACL_DIS, BTYPE, TO_DATE, FROM_DATE FROM ICOMBOARD WHERE STATUS != 'D'
AND BTYPE NOT IN ('BD', 'QA')
AND BTYPE = #{sbtype}
AND ACL = #{sacl}
ORDER BY REG_DATE DESC

