/*updateInfoReferenceLCount*/
UPDATE ICOMBOARD
   SET LCOUNT = LCOUNT + 1
 WHERE STATUS <> 'D' AND BID = #{BID} AND BTYPE = #{BTYPE}


/*updateMasterMdAmInfoReferenceDetail*/
UPDATE ICOMBOARD
   SET CONTEXT = #{CONTEXT}, SUBJECT = #{SUBJECT}, ACL = #{ACL}	, FROM_DATE = REPLACE(#{FROM_DATE},'/',''), TO_DATE = REPLACE(#{TO_DATE},'/','')
 WHERE BID = #{BID} AND BTYPE = #{BTYPE}

		/*deleteMasterMdAmInfoReferenceDetail*/

 		 	DELETE FROM  ICOMBOARD 
				WHERE BID = #{BID}		
				AND BTYPE = #{BTYPEBTYPE}
